// ============================================
// VALIDATION INPUT - MCP Tenant Resolve
// ============================================

const input = $input.first().json;
const body = input.body || input;
const ctx = body.context || {};

const errors = [];

const action = body.action || ctx.action;
const userId = body.user_id || ctx.user_id;
const guildId = body.guild_id || ctx.guild_id;
const backendApiUrl = body.backend_api_url || ctx.backend_api_url;
const backendServiceToken = body.backend_service_token || ctx.backend_service_token;

if (!action || action !== 'resolve') errors.push('action must be "resolve"');
if (!userId) errors.push('user_id requis');
if (!guildId) errors.push('guild_id requis');
if (!backendApiUrl) errors.push('backend_api_url requis');
if (!backendServiceToken) errors.push('backend_service_token requis');

if (errors.length > 0) {
  return { valid: false, errors, user_id: userId, guild_id: guildId };
}

return {
  valid: true,
  user_id: userId,
  guild_id: guildId,
  backend_api_url: backendApiUrl,
  backend_service_token: backendServiceToken,
  startTime: Date.now()
};

const input = $input.first().json;
return {
  success: false,
  error: { code: 'VALIDATION_ERROR', message: input.errors.join(', ') },
  user_id: input.user_id,
  guild_id: input.guild_id
};

// Return raw API response - plugin handles verification
const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const latencyMs = Date.now() - (prevData.startTime || Date.now());

// Handle array response from API
const apiData = Array.isArray(input) ? input[0] : input;

// Check for HTTP error
if (input.error || input.statusCode >= 400) {
  return {
    success: false,
    error: { code: 'API_ERROR', message: input.error?.message || 'API call failed' },
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    latency_ms: latencyMs
  };
}

// Return data directly - plugin will check tenant_id
return {
  success: true,
  data: apiData,
  user_id: prevData.user_id,
  guild_id: prevData.guild_id,
  latency_ms: latencyMs
};
